import {computed,ref,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {IconHeart,IconShare,IconArrowLeft,IconArrowRight,IconHandMove,IconVolume,IconChevronRight} from '@tabler/icons-vue'
