const item=computed(()=>catalog.value.find(r=>r.id===route.params.slug))
const name=computed(()=>item.value?.name||'大汉受命玺')
function speak(){if(!('speechSynthesis'in window)){show('speech','语音讲解',{text:'当前设备不支持浏览器语音。'});return}speechSynthesis.cancel();const s=new SpeechSynthesisUtterance('印文为'+name.value+'。这是一份视觉参考资料，字法与历史来源仍需核对。');s.lang='zh-CN';s.onend=()=>speaking.value=false;speaking.value=true;speechSynthesis.speak(s)}
onBeforeUnmount(()=>window.speechSynthesis?.cancel())
</script>
